# [역할: 당신은 소설 속 "{{name}}"({{role}})입니다]
당신은 지금부터 소설 속 등장인물 "{{name}}" 본인이 되어 모든 대화와 행동을 100% 캐릭터의 관점에서 직접 수행합니다.

## 1. 인물 기본 정체성 (Core Identity)
- 이름: {{name}} ({{role}})
- 신분/프로필: {{profile_summary}}
- 외모/복장: {{appearance}}

## 2. 성격 및 내면 심리 (Personality)
{{personality}}

## 3. 고유 말투 및 호칭 규칙 (Speech Tone)
- 어조 및 호칭: {{speech_tone}}
- 특유의 행동/버릇: {{behavior_patterns}}

## 4. 대표 대사 예시 (말투/톤 모방 가이드)
{{dialogue_examples}}

code:
// 1) 이름 / 역할 파싱
const nameRoleRaw = input.name_role || input.name || '';
let charName = '';
let charRole = '';
if (nameRoleRaw.includes('/')) {
  const parts = nameRoleRaw.split('/');
  charName = parts[0].trim();
  charRole = parts.slice(1).join('/').trim();
} else {
  charName = nameRoleRaw.trim();
  charRole = (input.role || '').trim();
}
charName = charName || '미정';
charRole = charRole || '등장인물';

// 2) 호불호 파싱
const prefRaw = input.preferences || '';
let likesRaw = input.likes || '';
let dislikesRaw = input.dislikes || '';
if (prefRaw.includes('/')) {
  const parts = prefRaw.split('/');
  likesRaw = parts[0].trim();
  dislikesRaw = parts.slice(1).join('/').trim();
} else if (prefRaw) {
  likesRaw = prefRaw.trim();
}
const likesList = likesRaw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);
const dislikesList = dislikesRaw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);

// 3) 대사 및 버릇 파싱
const dialogueList = (input.dialogue_examples || '').split('\n').map(s => s.trim()).filter(Boolean);
const habitList = (input.behavior_patterns || '').split('\n').map(s => s.trim()).filter(Boolean);

// 4) 로어 전체 JSON (소설 JSON 빌더 호환)
const loreJson = {
  name: charName,
  role: charRole,
  profile: input.profile_summary || '',
  appearance: input.appearance || '',
  special_ability: input.special_ability || '',
  preferences: {
    likes: likesList,
    dislikes: dislikesList
  },
  past_background_and_motivation: input.past_and_motivation || '',
  speech_style: {
    tone: input.speech_tone || '',
    examples: dialogueList
  },
  personality: { description: input.personality || '' },
  behavior_patterns: { common_habits: habitList },
  extra_notes: input.extra_notes || ''
};

// 5) 🌟 키워드 트리거용 동적 로어북 엔트리 자동 생성
function extractKeywords(text) {
  if (!text) return [];
  const list = text.split(/[,/\n]+/).map(s => s.trim().replace(/^[•\-*\d.]+\s*/, '')).filter(s => s.length >= 2);
  const words = [];
  for (const item of list) {
    words.push(item);
    item.split(/\s+/).forEach(w => {
      const clean = w.replace(/[^\w가-힣]/g, '');
      if (clean.length >= 2 && clean.length <= 10) words.push(clean);
    });
  }
  return Array.from(new Set(words));
}

const dynamicLorebookEntries = [
  {
    id: `${charName}_ability`,
    title: `${charName}의 특수 능력 및 기술`,
    keys: [charName + ' 능력', charName + ' 스킬', '능력', '스킬', '마법', '전투', ...extractKeywords(input.special_ability)],
    content: `${charName}의 특수 능력: ${input.special_ability || '없음'}`
  },
  {
    id: `${charName}_preferences`,
    title: `${charName}의 취향 및 호불호`,
    keys: [charName + ' 취향', '좋아하는', '싫어하는', '음식', ...likesList, ...dislikesList],
    content: `${charName}의 호불호: 좋아하는 것(${likesList.join(', ') || likesRaw || '없음'}) / 싫어하는 것(${dislikesList.join(', ') || dislikesRaw || '없음'})`
  },
  {
    id: `${charName}_past`,
    title: `${charName}의 과거사 및 비밀/동기`,
    keys: [charName + ' 과거', charName + ' 비밀', '과거', '비밀', '동기', '트라우마', ...extractKeywords(input.past_and_motivation)],
    content: `${charName}의 과거사 및 행동 동기: ${input.past_and_motivation || '없음'}`
  },
  {
    id: `${charName}_extra`,
    title: `${charName}의 소지품 및 특이사항`,
    keys: [charName + ' 소지품', '소지품', '가방', '장검', '약점', ...extractKeywords(input.extra_notes)],
    content: `${charName}의 기타 설정/소지품: ${input.extra_notes || '없음'}`
  }
].filter(entry => entry.content && !entry.content.endsWith('없음'));

// 6) 마크다운 변수 치환
const vars = {
  name: charName,
  role: charRole,
  profile_summary: input.profile_summary || '',
  profile: input.profile_summary || '',
  appearance: input.appearance || '',
  special_ability: input.special_ability || '',
  likes: likesList.join(', ') || likesRaw,
  dislikes: dislikesList.join(', ') || dislikesRaw,
  past_and_motivation: input.past_and_motivation || '',
  speech_tone: input.speech_tone || '',
  dialogue_examples: dialogueList.map(d => '- ' + d).join('\n'),
  personality: input.personality || '',
  behavior_patterns: habitList.join(', '),
  extra_notes: input.extra_notes || ''
};

function renderTemplate(tpl, data) {
  return tpl.replace(/\{\{\s*(\w+)\s*\}\}|\{\s*(\w+)\s*\}/g, (match, p1, p2) => {
    const k = p1 || p2;
    return data[k] !== undefined ? data[k] : match;
  });
}

let rawTemplate = (input.custom_persona_md || '').trim();

if (!rawTemplate) {
  rawTemplate = `# [역할: 당신은 소설 속 "${charName}"(${charRole})입니다]
당신은 지금부터 소설 속 등장인물 "${charName}" 본인이 되어 모든 대화와 행동을 100% 캐릭터의 관점에서 직접 수행합니다.

## 1. 인물 기본 정체성 (Core Identity)
- 이름: {{name}} ({{role}})
- 신분/프로필: {{profile_summary}}
- 외모/복장: {{appearance}}

## 2. 성격 및 내면 심리 (Personality)
{{personality}}

## 3. 고유 말투 및 호칭 규칙 (Speech Tone)
- 어조 및 호칭: {{speech_tone}}
- 특유의 행동/버릇: {{behavior_patterns}}

## 4. 대표 대사 예시 (말투/톤 모방 가이드)
{{dialogue_examples}}`;
}

const personaMd = renderTemplate(rawTemplate, vars);

return {
  '등장인물 데이터': {
    lore: loreJson,
    persona_md: personaMd,
    lorebook_entries: dynamicLorebookEntries,
    list: [loreJson, personaMd, dynamicLorebookEntries]
  }
};

const choice = input.selectedOption || input.selectedChoice || 'A';
const dataA = input['선택지 A 데이터'] || input['in_1'] || '';
const dataB = input['선택지 B 데이터'] || input['in_2'] || '';
const result = (choice === 'B' || choice === 'in_2') ? dataB : dataA;
return { '최종 선택 데이터': result || '(선택된 데이터 내용 없음)' };

const provider = input['AI 플랫폼'] || input.provider || 'Google (Gemini)';
const model = input['AI 모델'] || input.model || 'gemini-3.5-flash';
const apiKey = input['API Key'] || input.apiKey || '';
const temperature = parseFloat(input['창의성 (Temperature)'] || input.temperature || '0.7');
return {
  'AI 설정 데이터': {
    provider,
    model,
    apiKey: apiKey ? (apiKey.slice(0, 7) + '...' + apiKey.slice(-4)) : '(API Key 미설정)',
    rawApiKey: apiKey,
    temperature: isNaN(temperature) ? 0.7 : temperature
  }
};

const config = input['AI 설정'] || input['AI 설정 데이터'] || input['in_1'] || {};
const prompt = input['프롬프트 / 본문'] || input['프롬프트 텍스트'] || input['in_2'] || input.input || '';

if (!prompt || !String(prompt).trim()) {
    return { '생성 결과': '(입력된 프롬프트 또는 텍스트가 없습니다)' };
}

const provider = (typeof config === 'object' ? (config.provider || '') : '').toLowerCase();
const model = (typeof config === 'object' ? config.model : '') || 'gemini-1.5-flash';
const apiKey = (typeof config === 'object' ? (config.rawApiKey || config.apiKey) : '') || '';
const temperature = (typeof config === 'object' && config.temperature !== undefined) ? Number(config.temperature) : 0.7;

let generatedText = '';

try {
    if (provider.includes('google') || provider.includes('gemini') || model.startsWith('gemini')) {
        if (!apiKey || apiKey === '(API Key 미설정)') throw new Error('Gemini API Key가 설정되지 않았습니다.');
        const targetModel = model || 'gemini-1.5-flash';
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${targetModel}:generateContent?key=${apiKey}`;
        const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ parts: [{ text: String(prompt) }] }],
                generationConfig: { temperature: isNaN(temperature) ? 0.7 : temperature }
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        generatedText = data.candidates?.[0]?.content?.parts?.[0]?.text || '(응답 내용 없음)';
    } else if (provider.includes('anthropic') || provider.includes('claude') || model.startsWith('claude')) {
        if (!apiKey || apiKey === '(API Key 미설정)') throw new Error('Claude API Key가 설정되지 않았습니다.');
        const res = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': apiKey,
                'anthropic-version': '2023-06-01',
                'dangerously-allow-browser': 'true'
            },
            body: JSON.stringify({
                model: model || 'claude-3-5-haiku-20241022',
                max_tokens: 4096,
                temperature: isNaN(temperature) ? 0.7 : temperature,
                messages: [{ role: 'user', content: String(prompt) }]
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        generatedText = data.content?.[0]?.text || '(응답 내용 없음)';
    } else if (provider.includes('ollama') || provider.includes('local') || model.includes('llama') || model.includes('qwen') || (!apiKey && provider.includes('custom'))) {
        const targetModel = model || 'llama3';
        const res = await fetch('http://localhost:11434/api/generate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: targetModel,
                prompt: String(prompt),
                stream: false,
                options: { temperature: isNaN(temperature) ? 0.7 : temperature }
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error);
        generatedText = data.response || '(응답 내용 없음)';
    } else {
        if (!apiKey || apiKey === '(API Key 미설정)') throw new Error('OpenAI API Key가 설정되지 않았습니다.');
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify({
                model: model || 'gpt-4o-mini',
                temperature: isNaN(temperature) ? 0.7 : temperature,
                messages: [{ role: 'user', content: String(prompt) }]
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
        generatedText = data.choices?.[0]?.message?.content || '(응답 내용 없음)';
    }
} catch (err) {
    generatedText = `[AI 생성 오류: ${err.message}]`;
}

return { '생성 결과': generatedText };

return {
  '세계관 데이터': {
    title: input.title || '',
    tags: input.tags || input.genre || '',
    logline: input.logline || '',
    background_lore: input.background_lore || ''
  }
};

return {
  '고유명사 데이터': {
    type: input.type || '기타',
    term: input.term || '',
    desc: input.desc || ''
  }
};

return {
  '스타일 가이드': {
    project_meta: {
      role: input.role || '',
      task: '소설 본문 및 씬 설계도 작성'
    },
    core_experience_goal: {
      primary_emotion: input.experience_goal || '',
      narrative_focus: '주인공의 능력과 문제 해결, 히로인과의 상호작용'
    },
    writing_style_guide: {
      narrative_perspective: input.narrative_perspective || '3인칭 전지적 작가 시점',
      tone_and_style: input.tone_style || '',
      writing_rules: (input.writing_rules || input.formatting_rules || '').split('\n').filter(Boolean)
    }
  }
};

const events = (input.must_include_events || '').split('\n').filter(Boolean);
return {
  '챕터 스코프': {
    episode_notation: input.episode_notation || '',
    scene_goal: input.scene_goal || '',
    must_include_events: events.length > 0 ? events : [(input.must_include_events || '')]
  }
};

return {
  '복선 데이터': {
    active_hooks: [
      {
        id: input.hook_id || '복선',
        hidden_truth: input.hidden_truth || '',
        observable_clue: input.observable_clue || '',
        reveal_stage: input.reveal_stage || ''
      }
    ]
  }
};

return {
  'AI 작업 지시': {
    request: {
      command: input.command || 'WRITE_CHAPTER',
      instruction: input.instruction || '',
      output_requirements: input.output_requirements || ''
    },
    task: input.task || ''
  }
};

return {
  '지난 회차 데이터': {
    episode_title: input.episode_title || '',
    summary: input.summary || '',
    key_points: input.key_points || input.impact || ''
  }
};

const raw = input.rawInputs || {};
let meta = input['AI 작업 지시'] || input['AI 작업 메타'] || {};
let world = input['세계관 설정'] || input['세계관 데이터'] || {};
let properNouns = {};
let previousEpisodes = [];
let activeHooks = [];
let style = input['스타일 가이드'] || {};
let chapter = input['챕터 스코프'] || input['현재 챕터 스코프'] || {};
let characters = [];

const ingestItem = (d) => {
  if (!d || typeof d !== 'object') return;
  if (Array.isArray(d)) {
    d.forEach(sub => ingestItem(sub));
    return;
  }
  if (d.lore && typeof d.lore === 'object') {
    ingestItem(d.lore);
    return;
  }

  if (d.request || d.task) meta = { ...meta, ...d };
  if (d.title || d.background_lore) world = { ...world, ...d };

  // 단일/다중 고유명사 카드 취합
  if (d.term) {
    const catKey = d.type || '기타';
    if (!properNouns[catKey]) properNouns[catKey] = [];
    if (!properNouns[catKey].some(item => item.term === d.term)) {
      properNouns[catKey].push({ term: d.term, desc: d.desc || '' });
    }
  }
  if (d['장소'] || d['길드'] || d['세력 / 길드'] || d['현상'] || d['아이템']) {
    properNouns = { ...properNouns, ...d };
  }

  // 지난 회차 줄거리 요약 카드 취합
  if (d.episode_title || d.summary) {
    if (!previousEpisodes.some(ep => ep.episode === (d.episode_title || d.title))) {
      previousEpisodes.push({
        episode: d.episode_title || d.title || '회차',
        summary: d.summary || '',
        key_points: d.key_points || d.impact || ''
      });
    }
  }

  // 복선 노드 다중 취합 (단일 카드 또는 배열)
  if (d.active_hooks && Array.isArray(d.active_hooks)) {
    d.active_hooks.forEach(h => {
      if (!activeHooks.some(existing => existing.id === h.id && existing.hidden_truth === h.hidden_truth)) {
        activeHooks.push(h);
      }
    });
  } else if (d.hook_id || d.hidden_truth || d.observable_clue) {
    if (!activeHooks.some(existing => existing.id === (d.hook_id || d.id))) {
      activeHooks.push({
        id: d.hook_id || d.id || '복선',
        hidden_truth: d.hidden_truth || '',
        observable_clue: d.observable_clue || '',
        reveal_stage: d.reveal_stage || ''
      });
    }
  }

  if (d.project_meta && !d.request) style = { ...style, ...d };
  if (d.writing_style_guide) style = { ...style, ...d };
  if (d.episode_notation || d.must_include_events) chapter = { ...chapter, ...d };
  if (d.name && (d.role || d.traits || d.personality || d.speech_style)) {
    if (!characters.some(c => c.name === d.name)) characters.push(d);
  }
};

Object.values(raw).forEach(n => {
  const d = n.output || n.data;
  if (typeof d === 'string' && d.includes('《') && d.includes('소속:')) {
    characters.push({ description: d });
  } else {
    ingestItem(d);
  }
});

const charInput = input['등장인물'] || input['등장인물 (다중)'] || input['등장인물 데이터'] || input['프로필 데이터'];
if (charInput) ingestItem(charInput);

const histInput = input['지난 회차 (다중)'] || input['지난 회차 데이터'];
if (histInput) ingestItem(histInput);

const dictInput = input['고유명사 (다중)'] || input['고유명사 데이터'] || input['고유명사 사전'];
if (dictInput) ingestItem(dictInput);

const hookInput = input['복선 데이터 (다중)'] || input['복선 데이터'];
if (hookInput) ingestItem(hookInput);

const reqObj = meta.request || {};

const finalJson = {
  request: {
    command: reqObj.command || 'WRITE_CHAPTER',
    instruction: reqObj.instruction || '아래의 [설정값]과 [지금까지의 줄거리]를 완벽히 분석하여, [현재 챕터 범위]에 해당하는 소설 본문을 즉시 작성하시오.',
    output_requirements: reqObj.output_requirements || '사족이나 설명 없이 오직 소설 본문 텍스트(대사 및 지문)만을 출력할 것.'
  },
  project_meta: {
    role: style.project_meta?.role || '인기 웹소설 작가',
    task: meta.task || style.project_meta?.task || '소설 본문 작성'
  },
  core_experience_goal: style.core_experience_goal || { primary_emotion: '카타르시스, 도파민' },
  world_settings: world,
  characters: characters,
  proper_nouns_dict: properNouns,
  previous_episodes_history: previousEpisodes,
  foreshadowing_registry: { active_hooks: activeHooks },
  current_chapter_scope: chapter,
  writing_style_guide: style.writing_style_guide || { narrative_perspective: '3인칭 전지적 작가 시점' }
};

const jsonText = JSON.stringify(finalJson, null, 2);
return { '완성된 프롬프트': jsonText };
